from collections import deque
def solve(g,bg=7,fill=3):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[r[:] for r in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg or seen[r][c]: continue
            q=deque([(r,c)]); seen[r][c]=True; comp=[]; h_edge=w_edge=False
            while q:
                x,y=q.popleft(); comp.append((x,y))
                if x in (0,H-1) or y in (0,W-1): (h_edge,w_edge)=(True,True)
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<H and 0<=b<W and not seen[a][b] and g[a][b]==bg:
                        seen[a][b]=True; q.append((a,b))
            if not(h_edge or w_edge):
                for x,y in comp: out[x][y]=fill
    return out
